/* From Uiverse.io by vinodjangid07 - Tags: button, hover, logout */
.__UIV_SCOPE__ .Btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 45px;
  height: 45px;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition-duration: .3s;
  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.199);
  background-color: rgb(255, 65, 65);
}

/* plus sign */
.__UIV_SCOPE__ .sign {
  width: 100%;
  transition-duration: .3s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .sign svg {
  width: 17px;
}

.__UIV_SCOPE__ .sign svg path {
  fill: white;
}
/* text */
.__UIV_SCOPE__ .text {
  position: absolute;
  right: 0%;
  width: 0%;
  opacity: 0;
  color: white;
  font-size: 1.2em;
  font-weight: 600;
  transition-duration: .3s;
}
/* hover effect on button width */
.__UIV_SCOPE__ .Btn:hover {
  width: 125px;
  border-radius: 40px;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .Btn:hover .sign {
  width: 30%;
  transition-duration: .3s;
  padding-left: 20px;
}
/* hover effect button's text */
.__UIV_SCOPE__ .Btn:hover .text {
  opacity: 1;
  width: 70%;
  transition-duration: .3s;
  padding-right: 10px;
}
/* button click effect*/
.__UIV_SCOPE__ .Btn:active {
  transform: translate(2px ,2px);
}
